from pathlib import Path
ROOT=Path(__file__).parent
def transform(file,fn):
 p=ROOT/file;p.write_text(fn(p.read_text(encoding='utf-8')),encoding='utf-8')
transform('tests/test_improvements.py',lambda s:s.replace('from logic_arena.neural import NeuralAgent, NeuralPolicy','from logic_arena.neural import NeuralAgent, NeuralPolicy\nfrom logic_arena.general import GarryView').replace("patch.object(NeuralPolicy, 'logits'","patch.object(GarryView, 'logits'").replace("patch.object(NeuralPolicy,'logits'","patch.object(GarryView,'logits'"))
transform('tests/test_versions.py',lambda s:s.replace('without_dimension_changes','with_unified_model').replace("self.assertEqual(len({game['ai']['codename'] for game in games}),6)","self.assertEqual({game['ai']['codename'] for game in games},{'garry'})").replace("'1.1.0'","'2.0.0'"))
def html(s):
 s=s.replace('Entraînez de vrais réseaux neuronaux sur six jeux logiques. Regardez-les jouer ou affrontez-les.','Garry, un modèle neuronal général pour six jeux. Entraînez-le, regardez-le jouer ou affrontez-le.')
 s=s.replace('Six jeux, de vrais réseaux neuronaux.','Garry, un seul modèle pour six jeux.').replace('Six jeux. Un cerveau partagé.','Garry 2.0.0 · Un modèle, six jeux.').replace('Encodeurs spécialisés → module commun de 48 neurones → six têtes d’action.','Les connaissances des six jeux réunies dans un modèle unique.').replace('MLP · PARTAGÉ','GARRY · 2.0.0').replace('18 → 48 → 9','1912 → 48 → 48 → 818').replace('1 353 paramètres','134 258 paramètres').replace('Les modèles sont sauvegardés dans ce navigateur.','Garry est sauvegardé dans ce navigateur.').replace('MODÈLES EXPORTABLES','GARRY EXPORTABLE')
 s=s.replace('Chaque jeu utilise un encodeur spécialisé de 48 neurones, un module commun de 48 neurones partagé avec les cinq autres jeux, puis une tête d’action spécifique.','Garry utilise un encodeur unique de 1 912 entrées, deux couches de 48 neurones et une sortie unique de 818 actions. Le jeu active ses caractéristiques et ses actions légales. Tous les jeux utilisent les mêmes matrices, le même modèle en mémoire et le même fichier exporté.')
 s=s.replace('Les modèles initiaux ont appris à imiter des solveurs.','Les connaissances initiales des six politiques ont été réunies par une fusion algébrique des poids.').replace('Entraîner un jeu modifie le module commun utilisé par les six jeux.','Entraîner un jeu modifie Garry, notamment ses biais et son module central utilisés par les six jeux.').replace('Les modèles appris sont conservés','Les poids appris de Garry sont conservés')
 return s
transform('web/index.html',html)
transform('web/connect4.js',lambda s:s.replace("const ODD=CENTER.reduce((m,c)=>m|(21n<<BigInt(c*7)),0n);\n",'').replace("if(!depth&&!forced){const ownThreats=winningPositions(bits[root],mask),enemyThreats=winningPositions(bits[3-root],mask),favored=root===1?ODD:BOARD^ODD;\n   const value=score+100*count(ownThreats)-110*count(enemyThreats)+80*count(ownThreats&favored)-90*count(enemyThreats&(BOARD^favored));\n   return p===root?value:-value;\n  }","if(!depth&&!forced)return p===root?score:-score;"))
